import {campbellPath,campbellPearson} from './campbell-guide.js';
import {mountAssistant} from './bridgeassist.js?v=library-4';
import {questionById} from './conversation-bank.js';
import {loadVideoSuggestions,videoPreview,timeLabel} from './video-recommendations.js';
import {findVideos} from './video-search.js';
import {loadVideoNotes,loadVideoTranscript} from './video-transcript.js';

const host = document.querySelector('#workspace-assistant');
const panel = document.querySelector('#workspace-materials');
const toggle = document.querySelector('#workspace-toggle');
const close = document.querySelector('#workspace-close');
const resizer = document.querySelector('#workspace-resizer');
const workspace = document.querySelector('.workspace');
const videoDragType = 'application/x-biobridge-video';
const attachment = document.createElement('div');
attachment.className = 'workspace-attachment';
attachment.hidden = true;
const attachmentStatus = document.createElement('p');
attachmentStatus.className = 'workspace-attachment-status small';
attachmentStatus.setAttribute('role','status');
let attachedTrack;
let attachRequest = 0;
let paneWidth;
let lastAutoReply;
const strip = document.querySelector('#workspace-tabs');
const indexTab = {
  button: document.querySelector('#workspace-index-tab'),
  content: document.querySelector('#workspace-index')
};
const tabs = new Map();
const empty = document.querySelector('#workspace-empty');
const list = document.querySelector('#workspace-links');
const filters = [...document.querySelectorAll('[data-material]')];
const narrow = matchMedia('(max-width: 780px)');

let resources = new Map();
let selected = 'sources';
let dismissed = false;
let active = indexTab;
let nextTabId = 0;

function showPanel(open) {
  if (!open && active.resource?.id) active.frame.removeAttribute('src');
  panel.hidden = !open;
  if (open) loadActiveVideo();
  toggle.setAttribute('aria-expanded', String(open));
  resizer.hidden = !open || narrow.matches;
  if (open && !narrow.matches) sizePanel();
  host.inert = open && narrow.matches;
}

function describeLink(link) {
  const url = new URL(link.href);
  if (!['http:', 'https:'].includes(url.protocol)) return null;
  if (url.href === campbellPearson) return null;
  if (['www.youtube.com', 'youtube.com', 'youtu.be'].includes(url.hostname)) return null;
  if (url.origin === 'https://www.google.com' && /^\/maps\/(?:dir|search)\//.test(url.pathname)) {
    if (!link.dataset.mapEmbed) return null;
    const frame = new URL(link.dataset.mapEmbed);
    if (frame.origin !== url.origin || frame.pathname !== '/maps/embed') return null;
    return {url,title:link.dataset.campusTitle,type:'maps',mapEmbed:frame.href};
  }
  let type = 'sources';
  let id;
  if (url.origin === location.origin) {
    if (url.pathname === '/video-sources.html') {
      id = url.searchParams.get('v');
      if (id && !/^[\w-]{11}$/.test(id)) return null;
      type = 'videos';
    } else if (url.pathname === '/handouts.html' || url.pathname.startsWith('/handouts/') ||
               url.pathname === '/study/guide.html' || url.pathname === '/study/periodic-table.html') {
      type = 'handouts';
    }
  }
  const reply = link.closest('.chat-message.assistant');
  return {url, title: link.textContent.trim(), type, id, search: Object.hasOwn(link.dataset,'videoSearch'), context: reply?.querySelector('p')?.textContent};
}

function selectType(type) {
  selected = type;
  filters.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.material === type)));
  list.replaceChildren();
  const matching = [...resources.values()].filter(resource => (resource.type === type || (type === 'sources' && resource.type === 'maps')));
  empty.textContent = matching.length ? '' : 'No ' + type + ' linked in this conversation yet.';
  empty.hidden = matching.length > 0;

  for (const resource of matching) {
    const item = document.createElement('li');
    const link = document.createElement('a');
    link.href = resource.url.href;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = resource.title;
    item.append(link);
    list.append(item);
  }
}

function loadActiveVideo() {
  if (!active.resource?.id || active.frame.hasAttribute('src')) return;
  active.frame.src = active.embed + (active.playOnOpen ? '&autoplay=1' : '');
  active.playOnOpen = false;
}

function activate(tab) {
  if (active !== tab) {
    if (active.resource?.id) active.frame.removeAttribute('src');
    active.button.setAttribute('aria-selected', 'false');
    active.button.tabIndex = -1;
    active.content.hidden = true;
    active = tab;
    tab.button.setAttribute('aria-selected', 'true');
    tab.button.tabIndex = 0;
    tab.content.hidden = false;
    assistant.setVideoContext(attachedTrack?.video ?? tab.video ?? null);
  }
  if (!panel.hidden) loadActiveVideo();
}

function closeResource(tab) {
  const open = [indexTab, ...tabs.values()];
  const position = open.indexOf(tab);
  if (active === tab) activate(open[position + 1] ?? open[position - 1]);
  tabs.delete(tab.key);
  toggle.hidden = !resources.size && !tabs.size;
  panel.classList.toggle('has-open-resource', tabs.size > 0);
  tab.group.remove();
  tab.content.remove();
  active.button.focus();
}

function externalLink(title, url) {
  const link = document.createElement('a');
  link.href = url;
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  link.textContent = title;
  return link;
}

function transcriptDialog(title, text) {
  const dialog = document.createElement('dialog');
  dialog.className = 'workspace-notice';
  dialog.setAttribute('aria-label',title);
  const heading = document.createElement('h2');
  heading.textContent = title;
  const detail = document.createElement('p');
  detail.textContent = text;
  const okay = document.createElement('button');
  okay.textContent = 'Close';
  okay.type = 'button';
  okay.addEventListener('click',()=>dialog.close());
  dialog.addEventListener('close',()=>dialog.remove(),{once:true});
  dialog.append(heading,detail,okay);
  document.body.append(dialog);
  dialog.showModal();
}

function dragVideo(node, video) {
  node.draggable = true;
  node.addEventListener('dragstart',event=>{
    event.dataTransfer.effectAllowed = 'copy';
    event.dataTransfer.setData(videoDragType,video.id);
  });
}

async function attachVideo(video) {
  const request = ++attachRequest;
  attachmentStatus.textContent = 'Looking for the transcript…';
  try {
    const track = await loadVideoTranscript(video);
    if (request !== attachRequest) return;
    if (!track) {
      transcriptDialog('Transcript unavailable','Unfortunately, a transcript for “'+video.title+'” is not available in BioBridge yet. You can still watch the video and use its study notes where available.');
      return;
    }
    const file = new File([track.cues.map(cue=>timeLabel(Math.floor(cue.start))+' '+cue.text).join('\n')],
      'Transcript of '+video.title.replace(/[\/\\:*?"<>|]/g,'–')+'.txt',{type:'text/plain'});
    attachedTrack = {file, track, video};
    assistant.setVideoContext(video);
    attachment.querySelector('span').textContent = file.name;
    attachment.hidden = false;
    if (narrow.matches) showPanel(false);
    assistant.focus();
  } catch {
    if (request === attachRequest) transcriptDialog('Transcript could not load','Try attaching the transcript again in a moment.');
  } finally {
    if (request === attachRequest) attachmentStatus.textContent = '';
  }
}

function showVideoSearch(tab) {
  const form = document.createElement('form');
  form.className = 'workspace-video-search';
  form.setAttribute('role','search');
  const label = document.createElement('label');
  label.textContent = 'Search video resources';
  const input = document.createElement('input');
  input.type = 'search';
  input.maxLength = 160;
  input.value = tab.resource.url.searchParams.get('q') ?? '';
  label.append(input);
  const status = document.createElement('p');
  status.className = 'small';
  status.setAttribute('role','status');
  status.textContent = 'Loading videos…';
  const results = document.createElement('ul');
  results.className = 'workspace-video-results';
  form.append(label);
  tab.content.append(form,status,results);
  let search;
  form.addEventListener('submit',event=>{event.preventDefault();search?.();});
  Promise.all([loadVideoSuggestions(),loadVideoNotes().catch(()=>({}))]).then(([{index,tags},notes])=>{
    search=()=>{
      const query=input.value.trim();
      const course=tab.resource.url.searchParams.get('course') || '';
      const matches=findVideos(index,{query,course});
      tab.original.href='/video-sources.html?'+new URLSearchParams({q:query,course});
      status.textContent=matches.length?'Showing '+Math.min(12,matches.length)+' of '+matches.length+' videos.':'No matches. Try a shorter search.';
      results.replaceChildren();
      for(const video of matches.slice(0,12)){
        const row=document.createElement('li');
        const preview=document.createElement('button');
        preview.type='button';
        preview.className='workspace-video-result';
        const image=document.createElement('img');
        image.src='https://i.ytimg.com/vi/'+video.id+'/mqdefault.jpg';
        image.loading='lazy';
        image.alt='';
        const name=document.createElement('strong');
        name.textContent=video.title;
        const meta=document.createElement('small');
        meta.textContent=video.creator+' · '+timeLabel(video.duration);
        preview.append(image,name,meta);
        dragVideo(preview,video);
        preview.addEventListener('click',()=>openResource({
          url:new URL('/video-sources.html?v='+video.id,location.origin),title:video.title,type:'videos',id:video.id
        }));
        const summary=document.createElement('p');
        summary.className='small';
        summary.textContent=notes[video.id]?.summary || videoPreview(video,tags.get(video.topic));
        const attach=document.createElement('button');
        attach.type='button';
        attach.textContent='Attach transcript';
        attach.addEventListener('click',()=>attachVideo(video));
        row.append(preview,summary,attach);
        results.append(row);
      }
    };
    input.addEventListener('input',search);
    search();
  }).catch(()=>{status.textContent='The video catalog could not load. Use Open Video Sources to try again.';});
}

function createTab(key, resource) {
  const id = 'workspace-resource-' + ++nextTabId;
  const group = document.createElement('div');
  group.className = 'workspace-tab';
  group.setAttribute('role', 'presentation');
  const button = document.createElement('button');
  button.type = 'button';
  button.id = id + '-tab';
  button.textContent = resource.title;
  button.title = resource.title;
  button.setAttribute('role', 'tab');
  button.setAttribute('aria-selected', 'false');
  button.setAttribute('aria-controls', id);
  button.tabIndex = -1;
  const remove = document.createElement('button');
  remove.type = 'button';
  remove.className = 'workspace-tab-close';
  remove.textContent = '×';
  remove.setAttribute('aria-label', 'Close ' + resource.title);
  remove.tabIndex = -1;
  group.append(button, remove);

  const content = document.createElement('div');
  content.id = id;
  content.className = 'workspace-resource';
  content.setAttribute('role', 'tabpanel');
  content.setAttribute('aria-labelledby', button.id);
  content.tabIndex = 0;
  content.hidden = true;
  const heading = document.createElement('h3');
  heading.textContent = resource.title;
  const actions = document.createElement('div');
  actions.className = 'workspace-preview-actions';
  const original = externalLink(resource.search ? 'Open Video Sources ↗' : resource.id ? 'Open in Video Sources ↗' : resource.url.pathname === campbellPath && resource.url.origin === location.origin ? 'Open full reader ↗' : 'Open original ↗', resource.url.href);
  actions.append(original);
  const toolbar = document.createElement('div');
  toolbar.className = 'workspace-resource-head';
  toolbar.append(heading, actions);
  content.append(toolbar);

  const frame = document.createElement('iframe');
  frame.title = resource.title;
  const tab = {key, resource, group, button, content, frame, original};
  if (resource.search) {
    showVideoSearch(tab);
  } else if (resource.mapEmbed) {
    frame.className = 'workspace-document';
    frame.referrerPolicy = 'no-referrer';
    frame.src = resource.mapEmbed;
    content.append(frame);
  } else if (resource.id) {
    frame.className = 'workspace-video';
    frame.allow = 'autoplay; encrypted-media; picture-in-picture';
    frame.allowFullscreen = true;
    content.append(frame);
    const summarize = document.createElement('button');
    summarize.type = 'button';
    summarize.textContent = 'Summarize video';
    summarize.disabled = true;
    summarize.addEventListener('click', async () => {
      if (narrow.matches) showPanel(false);
      assistant.setVideoContext(tab.video);
      await assistant.ask('Summarize this video');
      assistant.setVideoContext(attachedTrack?.video ?? active.video ?? null);
      assistant.focus();
    });
    const attach = document.createElement('button');
    attach.type = 'button';
    attach.textContent = 'Attach transcript';
    attach.disabled = true;
    attach.addEventListener('click',()=>attachVideo(tab.video));
    actions.prepend(summarize,attach);
    loadVideoSuggestions().then(catalog => {
      tab.video = catalog?.index.find(row => row.video.id === resource.id)?.video;
      if (!tab.video || tabs.get(key) !== tab) return;
      heading.textContent = button.textContent = button.title = frame.title = tab.video.title;
      remove.setAttribute('aria-label', 'Close ' + tab.video.title);
      summarize.disabled = attach.disabled = false;
      dragVideo(button,tab.video);
      if (active === tab) assistant.setVideoContext(attachedTrack?.video ?? tab.video);
    }).catch(() => {});
  } else if (resource.url.pathname === campbellPath && resource.url.origin === location.origin) {
    original.textContent = 'Open reading guide in browser ↗';
    frame.className = 'workspace-document';
    frame.src = resource.url.href;
    content.append(frame);
  } else if (resource.url.hostname === 'www.ncbi.nlm.nih.gov' && resource.url.pathname.startsWith('/books/')) {
    const note = document.createElement('p');
    note.textContent = 'Read the full reference on NCBI Bookshelf using Open original.';
    toolbar.append(note);
    if (resource.context) {
      const label = document.createElement('h4');
      label.textContent = 'From the BridgeAssist reply';
      const excerpt = document.createElement('p');
      excerpt.textContent = resource.context;
      toolbar.append(label, excerpt);
    }
  } else {
    frame.className = 'workspace-document';
    if (resource.url.origin !== location.origin) {
      // These publishers use same-origin requests to render their embedded pages.
      const trustedFrames = ['https://openstax.org', 'https://map.concept3d.com'];
      frame.setAttribute('sandbox', trustedFrames.includes(resource.url.origin)
        ? 'allow-scripts allow-same-origin'
        : 'allow-scripts');
      const hint = document.createElement('p');
      hint.className = 'small';
      hint.textContent = 'If the publisher’s page does not load here, use Open original.';
      toolbar.append(hint);
    }
    frame.src = resource.url.href;
    content.append(frame);
  }

  tabs.set(key, tab);
  panel.classList.add('has-open-resource');
  strip.append(group);
  panel.append(content);
  button.addEventListener('click', () => activate(tab));
  remove.addEventListener('click', () => closeResource(tab));
  return tab;
}

function openResource(resource, {focus = true} = {}) {
  const isCampbell = resource.url.origin === location.origin && resource.url.pathname === campbellPath;
  const key = isCampbell ? campbellPath : resource.id ? 'video:' + resource.id : resource.url.href;
  const existing = tabs.get(key);
  const tab = existing ?? createTab(key, isCampbell ? {...resource, title:'Campbell Biology'} : resource);
  if (existing && isCampbell && resource.url.hash) {
    const locationInTab = tab.frame.contentWindow.location;
    if (locationInTab.pathname === campbellPath) locationInTab.hash = resource.url.hash;
    else tab.frame.src = resource.url.href;
    tab.original.href = resource.url.href;
  }
  if (resource.id) {
    const start = resource.url.searchParams.get('t');
    if (!tab.embed || start !== null) {
      const embed = new URLSearchParams({playsinline: '1', rel: '0'});
      if (start !== null && /^\d+$/.test(start)) {
        embed.set('start', start);
        tab.playOnOpen = true;
      }
      tab.embed = 'https://www.youtube-nocookie.com/embed/' + resource.id + '?' + embed;
      tab.original.href = resource.url.href;
      tab.frame.removeAttribute('src');
    }
  }
  dismissed = false;
  toggle.hidden = false;
  activate(tab);
  showPanel(true);
  if (focus || narrow.matches) tab.button.focus();
}

function interceptResource(event) {
  const link = event.target.closest('a[href]');
  if (!link || event.defaultPrevented || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
  const resource = describeLink(link);
  if (!resource?.title) return;
  event.preventDefault();
  openResource(resources.get(resource.url.href) ?? resource);
}

function syncResources(log) {
  const next = new Map();
  for (const link of log.querySelectorAll('.chat-message.assistant a[href]')) {
    const resource = describeLink(link);
    if (!resource || !resource.title) continue;
    next.set(resource.url.href, resource);
  }
  const first = !resources.size;
  resources = next;
  toggle.hidden = !resources.size && !tabs.size;
  toggle.querySelector('span').textContent = resources.size ? '(' + resources.size + ')' : '';
  if (!resources.size) {
    activate(indexTab);
    for (const tab of tabs.values()) {
      tab.group.remove();
      tab.content.remove();
    }
    tabs.clear();
    panel.classList.remove('has-open-resource');
    showPanel(false);
    dismissed = false;
    lastAutoReply = undefined;
    return;
  }
  const reply = [...log.querySelectorAll('article.chat-message.assistant')].at(-1);
  const target = reply?.querySelector('a[data-video-search], a[data-auto-open]');
  if (target && target !== lastAutoReply) {
    const resource = describeLink(target);
    lastAutoReply = target;
    if (resource) openResource(resource,{focus:false});
  }
  const firstType = resources.values().next().value.type;
  selectType(first ? (firstType==='maps'?'sources':firstType) : selected);
  if (!narrow.matches && !dismissed) showPanel(true);
}

const assistant = mountAssistant(host, {
  onConversationChange: syncResources,
  pastedTranscript: id=>attachedTrack?.video.id===id ? attachedTrack.track : undefined,
});
const composer = host.querySelector('.chat-form');
const attachmentName=document.createElement('span');
const removeAttachment=document.createElement('button');
removeAttachment.type='button';
removeAttachment.textContent='Remove';
removeAttachment.setAttribute('aria-label','Remove transcript attachment');
const clearAttachment=()=>{
  attachRequest++;
  attachedTrack=undefined;
  attachment.hidden=true;
  attachmentStatus.textContent='';
  assistant.setVideoContext(active.video ?? null);
};
removeAttachment.addEventListener('click',()=>{clearAttachment();assistant.focus();});
attachment.append(attachmentName,removeAttachment);
composer.prepend(attachment,attachmentStatus);
composer.querySelector('.clear-chat').addEventListener('click',clearAttachment);
composer.addEventListener('dragover',event=>{
  if(!event.dataTransfer.types.includes(videoDragType))return;
  event.preventDefault();
  event.dataTransfer.dropEffect='copy';
  composer.classList.add('workspace-drop-target');
});
composer.addEventListener('dragleave',event=>{
  if(!composer.contains(event.relatedTarget))composer.classList.remove('workspace-drop-target');
});
composer.addEventListener('drop',async event=>{
  composer.classList.remove('workspace-drop-target');
  if(!event.dataTransfer.types.includes(videoDragType))return;
  event.preventDefault();
  const id=event.dataTransfer.getData(videoDragType);
  const catalog=await loadVideoSuggestions().catch(()=>null);
  const video=catalog?.index.find(row=>row.video.id===id)?.video;
  if(video)attachVideo(video);
});
composer.querySelector('textarea').placeholder = 'Ask about science or type a math equation';
const caption = host.querySelector('.assistant-caption');
caption.textContent = 'Ask a science question or try “Give me an example question about gas laws.”';
const campbell = document.createElement('a');
campbell.href = campbellPath;
campbell.textContent = 'Open Campbell chapter guide';
campbell.className = 'workspace-textbook-link';
campbell.addEventListener('click', interceptResource);
caption.append(' ', campbell);
const library = document.createElement('a');
library.href = '/assistant.html?study=1';
library.textContent = 'Browse all 150,000 study records';
library.className = 'workspace-textbook-link';
library.addEventListener('click', event => {
  if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
  event.preventDefault();
  void assistant.browseLibrary();
});
caption.append(' ', library);
composer.querySelector('.clear-chat').textContent = 'New chat';

host.addEventListener('click', event => {
  if (event.target.closest('.chat-message.assistant a[href]')) interceptResource(event);
});
indexTab.content.addEventListener('click', interceptResource);
indexTab.button.addEventListener('click', () => activate(indexTab));
filters.forEach(button => button.addEventListener('click', () => selectType(button.dataset.material)));
strip.addEventListener('keydown', event => {
  const open = [indexTab, ...tabs.values()];
  const index = open.findIndex(tab => tab.button === event.target);
  if (index === -1) return;
  if (event.key === 'Delete' && index > 0) {
    event.preventDefault();
    closeResource(open[index]);
    return;
  }
  const positions = {
    ArrowLeft: (index - 1 + open.length) % open.length,
    ArrowRight: (index + 1) % open.length,
    Home: 0,
    End: open.length - 1
  };
  if (!Object.hasOwn(positions, event.key)) return;
  event.preventDefault();
  const next = open[positions[event.key]];
  activate(next);
  next.button.focus();
});
toggle.addEventListener('click', () => {
  dismissed = !panel.hidden;
  showPanel(!dismissed);
  if (!dismissed) close.focus();
});
function closePanel() {
  dismissed = true;
  showPanel(false);
  toggle.focus();
}
close.addEventListener('click', closePanel);
panel.addEventListener('keydown', event => {
  if (event.key === 'Escape') closePanel();
});
function sizePanel(width = paneWidth) {
  const minimum=280;
  const maximum=Math.max(minimum,Math.floor(workspace.clientWidth*.72));
  const value=Math.min(maximum,Math.max(minimum,Math.round(width ?? panel.getBoundingClientRect().width)));
  if(width!==undefined){
    paneWidth=value;
    panel.style.setProperty('--workspace-panel-width',value+'px');
  }
  resizer.setAttribute('aria-valuemin',String(minimum));
  resizer.setAttribute('aria-valuemax',String(maximum));
  resizer.setAttribute('aria-valuenow',String(value));
  resizer.setAttribute('aria-valuetext',value+' pixels');
}
resizer.addEventListener('pointerdown',event=>{
  if(event.button!==0)return;
  event.preventDefault();
  resizer.focus();
  resizer.setPointerCapture(event.pointerId);
});
resizer.addEventListener('pointermove',event=>{
  if(resizer.hasPointerCapture(event.pointerId))sizePanel(workspace.getBoundingClientRect().right-event.clientX);
});
resizer.addEventListener('keydown',event=>{
  const width=panel.getBoundingClientRect().width;
  const target={ArrowLeft:width+24,ArrowRight:width-24,Home:0,End:workspace.clientWidth}[event.key];
  if(target===undefined)return;
  event.preventDefault();
  sizePanel(target);
});
narrow.addEventListener('change',()=>showPanel(!panel.hidden));
new ResizeObserver(()=>{if(!panel.hidden&&!narrow.matches)sizePanel();}).observe(panel);

const params = new URLSearchParams(location.search);
const question = questionById(params.get('question'));
const topic = params.get('topic');
const studyItem = params.get('library');
if (studyItem && /^\d{1,6}$/.test(studyItem)) assistant.openLibrary(Number(studyItem));
else if (question) assistant.ask(question.prompt, question);
else if (params.get('study') === '1') assistant.browseLibrary({
  query: params.get('q'), course: params.get('course'), kind: params.get('type'), page: Number(params.get('page')) || 1
});
else if (params.get('practice') === '1') {
  const requestedCourse = params.get('course');
  if (/^(?:BIOL|CHEM) \d{4}$/.test(requestedCourse ?? '')) assistant.setCourse(requestedCourse);
  const query = (params.get('q') ?? '').trim().slice(0, 240);
  assistant.ask(query ? 'Give me a practice question about ' + query : 'Give me a practice question');
}
else if (topic && topic.length < 120) assistant.ask('Help me practice ' + topic);

import {campbellPath,campbellPearson,campbellRequest} from './campbell-guide.js';
import {loadVideoSuggestions,parseVideoRequest,suggestVideos,timeLabel,videoPreview} from './video-recommendations.js';
import {biologyCourse,courseComparison,topicGuide} from './course-context.js';
import {geneticsRequest} from './genetics.js';
import {atomicRequest,electronModel,atomicSymbol,electronSource,lewisSource,chargeSource,shapeSource,nistSource} from './atomic-tutor.js';
import {renderAtomic,renderLewis} from './atomic-visuals.js';
import {addPathway,pathwayRequest,addPunnett,addHardy,addPopulation,geneticsSource,hardySource,populationSource} from './biology-visuals.js';
