  const lesson=pathwayRequest(topic);
  if(lesson){addPathway(reply,lesson);return;}
  const cross=geneticsRequest(topic);
  if(cross&&!cross.unsupported){addPunnett(reply,cross);return;}
  if(/hardy.?weinberg/i.test(topic)){addHardy(reply);return;}
