    </form>
    <p data-status role="status" aria-live="polite"></p>
    <ol class="learning-matches" aria-label="Study results"></ol>
    <form data-pages aria-label="Result pages" hidden>
      <button type="button" data-previous>Previous</button>
      <label>Page <input name="page" type="number" min="1" value="1" required></label>
      <span data-limit></span>
      <button type="submit">Go</button>
      <button type="button" data-next>Next</button>
    </form>`;
  const search = host.querySelector('[data-search]');
  const pages = host.querySelector('[data-pages]');
  const query = search.elements.q;
  const collection = search.elements.course;
  const type = search.elements.type;
  const page = pages.elements.page;
  const status = host.querySelector('[data-status]');
  const list = host.querySelector('ol');
  const previous = pages.querySelector('[data-previous]');
  const next = pages.querySelector('[data-next]');
  const format = number => number.toLocaleString('en-US');
  let generation = 0;
  let current = 1;

  function apply(view) {
    list.replaceChildren();
    for (const item of view.results) {
      const row = document.createElement('li');
      const button = document.createElement('button');
      const detail = document.createElement('small');
      detail.textContent = (item.course === 'RESOURCES' ? 'Study resources' : item.course) +
        ' · ' + (item.kind === 'practice' ? 'Practice problem' : 'Question');
      button.type = 'button';
      button.append(detail, document.createTextNode(item.question));
      button.addEventListener('click', () => openRecord(item.position, item.kind === 'practice'));
      row.append(button);
      list.append(row);
    }
    current = view.page;
    status.textContent = view.count ? format(view.count) + ' matches · Page ' + format(view.page) +
      ' of ' + format(view.pageCount) : 'No matches. Try a shorter topic or a different collection.';
    pages.hidden = view.pageCount <= 1;
    page.value = view.page;
    page.max = view.pageCount;
    pages.querySelector('[data-limit]').textContent = 'of ' + format(view.pageCount);
    previous.disabled = view.page === 1;
    next.disabled = view.page === view.pageCount;
  }

  async function show(requestedPage = 1) {
    const ticket = ++generation;
    status.textContent = 'Loading study records…';
    try {
      const view = await libraryPage({query:query.value.trim(), course:collection.value,
        kind:type.value, page:requestedPage});
      if (ticket === generation) apply(view);
    } catch {
      if (ticket === generation) status.textContent = 'The records could not load. Try searching again.';
    }
  }

  search.addEventListener('submit', event => {event.preventDefault(); void show();});
  collection.addEventListener('change', () => void show());
  type.addEventListener('change', () => void show());
  pages.addEventListener('submit', event => {event.preventDefault(); void show(Number(page.value));});
  previous.addEventListener('click', () => void show(current - 1));
  next.addEventListener('click', () => void show(current + 1));
  try {
    const manifest = await libraryManifest();
    host.querySelector('[data-total]').textContent = format(manifest.questions) + ' questions and ' +
      format(manifest.practice) + ' practice problems. Choose one to open it here in chat.';
    for (const item of manifest.collections) {
      collection.add(new Option(item.course === 'RESOURCES' ? 'Study resources' : item.course, item.course));
    }
    query.value = (initial.query ?? '').slice(0, 1600);
    collection.value = [...collection.options].some(option => option.value === initial.course) ? initial.course : '';
    type.value = ['question','practice'].includes(initial.kind) ? initial.kind : '';
    await show(initial.page);
  } catch {
    status.textContent = 'The study library could not load. Reload the page to try again.';
  }
}

export const libraryVersion = 'v4';
const root = '/data/bridgeassist-full/' + libraryVersion + '/';
const stopWords = new Set('a an and are as ask at be but by can could did do does for from give has have help how i if in into is it its me my of on or please should so tell than that the their them then these they this those to use using was we were what when where which why will with would you your'.split(' '));
const cache = new Map();

export function normalizeQuestion(value) {
  return String(value).normalize('NFKC').replace(/[’‘]/g, "'").replace(/[‐‑–−]/g, '-')
    .toLowerCase().replace(/\s+/g, ' ').trim().replace(/[?!.]+$/, '');
}

export function exactQuestion(value) {
  return String(value).normalize('NFC').replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim().replace(/[?!.]+$/, '');
}

export function libraryTokens(value) {
  const words = normalizeQuestion(value).match(/\d+(?:\.\d+)?|[a-z][a-z0-9]+/g) ?? [];
  return [...new Set(words.filter(word => !stopWords.has(word)).map(word =>
    /^(?:laws|equations|proteins|cells|organelles|chromosomes|reactions|ratios|problems|solutions|questions|moles)$/.test(word)
      ? word.slice(0, -1) : word
  ))];
}

export function bucketFor(value) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) hash = Math.imul(hash ^ value.charCodeAt(i), 0x01000193);
  return (hash >>> 24).toString(16).padStart(2, '0');
}

async function read(path) {
  if (cache.has(path)) {
    const pending = cache.get(path);
    cache.delete(path);
    cache.set(path, pending);
    return pending;
  }
  const pending = fetch(root + path).then(async response => {
    if (!response.ok) throw Error('Study library file unavailable');
    if (!path.endsWith('.bin')) return response.json();
    return new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json();
  }).catch(error => {
    if (cache.get(path) === pending) cache.delete(path);
    throw error;
  });
  cache.set(path, pending);
  if (cache.size > 36) cache.delete(cache.keys().next().value);
  return pending;
}

export const libraryManifest = () => read('manifest.json');
export const librarySources = () => read('sources.json');

export async function libraryRecord(position) {
  const {total, shardSize} = await libraryManifest();
  if (!Number.isInteger(position) || position < 0 || position >= total) return null;
  const rows = await read('records/' + Math.floor(position / shardSize) + '.bin');
  return rows[position % shardSize];
}

export async function exactLibraryRecord(query, course = '') {
  const canonical = normalizeQuestion(query);
  if (canonical.length < 12 || canonical.length > 1600) return null;
  const index = await read('exact/' + bucketFor(canonical) + '.bin');
  const stored = Object.hasOwn(index, canonical) ? index[canonical] : undefined;
  if (stored === undefined) return null;
  const positions = Array.isArray(stored) ? stored : [stored];
  const eligible = (await Promise.all(positions.map(async position => ({position, record: await libraryRecord(position)}))))
    .filter(({record}) => !course || record.courses.includes(course) || record.primary_collection === 'RESOURCES');
  const same = eligible.find(({record}) => exactQuestion(record.question) === exactQuestion(query));
  if (same) return same;
  // Capitalization can change genotype and chemical notation in a numerical problem.
  return eligible.length === 1 && eligible[0].record.record_kind === 'question' ? eligible[0] : null;
}

export async function libraryPage({query = '', course = '', kind = '', page = 1, chat = false, exclude = []} = {}) {
  const manifest = await libraryManifest();
  const {total, shardSize, pageSize, collections} = manifest;
  const scope = collections.find(entry => entry.course === course) ?? {start: 0, end: total};
  const skipped = new Set(exclude);
  const within = position => position >= scope.start && position < scope.end && !skipped.has(position);
  const kindList = kind === 'question' || kind === 'practice' ? await read('lists/' + kind + '.bin') : null;
  const terms = libraryTokens(query).slice(0, 20);
  let positions;
  if (terms.length) {
    const buckets = await Promise.all(terms.map(term => read('terms/' + bucketFor(term) + '.bin')));
    const lists = terms.map((term, index) => Object.hasOwn(buckets[index], term) ? buckets[index][term] : [])
      .filter(list => list.length).sort((a, b) => a.length - b.length);
    if (!lists.length) return {results: [], count: 0, page: 1, pageCount: 1};
    const matchingKind = kindList ? new Set(kindList) : null;
    const scores = new Map();
    let bestCoverage = 0;
    for (const list of lists) {
      const weight = Math.log(1 + total / list.length);
      for (const position of list) {
        if (!within(position) || (matchingKind && !matchingKind.has(position))) continue;
        const score = scores.get(position) ?? {position, weight: 0, terms: 0};
        score.weight += weight;
        score.terms++;
        bestCoverage = Math.max(bestCoverage, score.terms);
        scores.set(position, score);
      }
    }
    const threshold = chat ? Math.max(1, terms.length <= 3 ? terms.length : Math.ceil(terms.length * .8))
      : Math.max(1, Math.min(bestCoverage, Math.ceil(lists.length * .55)));
    positions = [...scores.values()].filter(score => score.terms >= threshold)
      .sort((a, b) => b.terms - a.terms || b.weight - a.weight || a.position - b.position)
      .map(score => score.position);
    const exact = chat ? null : await exactLibraryRecord(query, course);
    if (exact && within(exact.position) && (!matchingKind || matchingKind.has(exact.position))) {
      positions = [exact.position, ...positions.filter(position => position !== exact.position)];
    }
  } else if (kindList) {
    positions = kindList.filter(within);
  }
  const count = positions?.length ?? scope.end - scope.start;
  const pageCount = Math.max(1, Math.ceil(count / pageSize));
  const current = Math.min(pageCount, Math.max(1, Math.floor(page) || 1));
  const offset = (current - 1) * pageSize;
  const selected = positions?.slice(offset, offset + pageSize) ??
    Array.from({length: Math.min(pageSize, count - offset)}, (_, index) => scope.start + offset + index);
  const results = await Promise.all(selected.map(async position => {
    const rows = await read('catalog/' + Math.floor(position / shardSize) + '.bin');
    const [id, kind, courseIndex, topic, question, family, topicTerms] = rows[position % shardSize];
    return {position, id, kind, course: collections[courseIndex].course, topic, question, family, topicTerms};
  }));
  return {results, count, page: current, pageCount};
}

import {LearningSession,followUpIntent} from './learning-session.mjs';
import {makePractice,recalculatePractice} from './practice-families.mjs';
import {exactLibraryRecord,exactQuestion,libraryRecord,librarySources} from './full-library.mjs?v=library-4';
import {findChatRecords,practiceRequest} from './library-chat-search.mjs?v=library-4';
const root='/data/bridgeassist-library/';
const stop=new Set('a an the is are was were do does did how what why can could would you i me my it this that of to in on for with and or from at use using please tell get question'.split(' '));
const normal=q=>String(q).normalize('NFKC').replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim().toLowerCase();
const tokens=q=>new Set(normal(q).match(/[a-z]+(?:\+[a-z]+)?|\d+(?:\.\d+)?/g)?.filter(t=>!stop.has(t))??[]);
const acronyms=new Set(['BIOL','CHEM','ATP','DNA','RNA','NAD','NADH','NADPH','FAD','SI','PV','VSEPR','ER']);
const entities=q=>[...String(q).matchAll(/\b(?:AA|Aa|aa|(?:[A-Z][a-z]?\d*){2,})\b/g)].map(m=>m[0]).filter(x=>!acronyms.has(x));
const numberSet=q=>new Set([...String(q).matchAll(/(?<![\w.])-?\d+(?:\.\d+)?/g)].map(m=>String(Number(m[0]))));
export function rankLibrary(query,index,course=''){
 const q=normal(query),qt=tokens(query),qe=entities(query);
 return index.filter(r=>!course||r.courses.includes(course)||r.primary_collection==='RESOURCES').map(r=>{
  const exact=q===normal(r.question)||(r.aliases??[]).some(a=>normal(a)===q);
  const rt=tokens(r.question+' '+r.topic),re=entities(r.question);
  if(qe.some(e=>!re.includes(e)))return {record:r,score:0,coverage:0,exact:false};
  let shared=0;for(const t of qt)if(rt.has(t))shared++;
  const coverage=qt.size?shared/qt.size:0;
  return {record:r,score:exact?100:coverage*7+shared*.25+(course&&r.courses.includes(course)?0.5:0),coverage,exact};
 }).sort((a,b)=>b.score-a.score);
}
export function createLibraryTutor({fetcher=fetch,fullRelease=false}={}){
 let loading,sources,index,version=0,selectedCourse='';const shards=new Map();
 let activeSources, exampleTopic, exercise, awaitingTopic=false, examples=new Set();
 const session=new LearningSession({recalculate:recalculatePractice});
 async function json(path){const response=await fetcher(root+path);if(!response.ok)throw Error('Learning library unavailable');return response.json();}
 function ready(){return loading??=Promise.all([json('index.json'),json('sources.json')]).then(([a,b])=>{index=a;sources=b;}).catch(error=>{loading=null;throw error;});}
 function reset(){version++;session.reset();activeSources=null;exampleTopic='';exercise=false;awaitingTopic=false;examples.clear();}
 async function startFull(record,ticket,{asExercise=false}={}){
  const fullSources=await librarySources();
  if(ticket!==version)return null;
  activeSources=fullSources;
  exercise=asExercise;
  const reply={...session.start(record),sources:fullSources,record,exercise};
  if(asExercise){
   reply.text='Try this '+(record.record_kind==='practice'?'practice problem.':'concept question.');
   reply.prompt=null;
  }
  return reply;
 }
 async function getRecord(entry){if(!shards.has(entry.shard))shards.set(entry.shard,json(entry.shard).catch(error=>{shards.delete(entry.shard);throw error;}));return (await shards.get(entry.shard)).find(r=>r.id===entry.id);}
 return {
  reset,
  async choose(item,asExercise){
   if(asExercise&&item.requestedTopic!==exampleTopic){
    exampleTopic=item.requestedTopic;
    examples.clear();
    examples.add(item.position);
   }
   return startFull(item.record,version,{asExercise});
  },
  async findRelated(query,course='',asResource=false){
   const topic=asResource?query.replace(/^.*?\b(?:find|locate|looking for|resources? for)\b\s*/i,''):query;
   const ticket=version;
   const matches=await findChatRecords({topic,course:asResource?'RESOURCES':course,kind:'question',count:3});
   if(ticket!==version||!matches.length)return null;
   if(matches.length===1&&matches[0].confidence>0&&!/\d/.test(topic))return startFull(matches[0].record,ticket);
   return {kind:'matches',text:'These saved questions may help. Choose one to open its explanation.',matches};
  },
  async open(position,course='',asExercise=false){
   reset();selectedCourse=course;
   const ticket=version;
   const record=await libraryRecord(position);
   return record?startFull(record,ticket,{asExercise}):null;
  },
  async respond(query,course=''){
   const intent=/^(?:what (?:is|are)|define)\b/i.test(query.trim())&&!/\b(?:this|that|these|those)\b/i.test(query)?null:followUpIntent(query);
   const named=/\b(BIOL|CHEM)\s*(1405|1406|1407|1411)\b/i.exec(query);
   const effective=named?named[1].toUpperCase()+' '+named[2]:course||(intent?selectedCourse:'');
   if(effective!==selectedCourse){reset();selectedCourse=effective;}
   const beforeLoad=version;
   const search=named?query.replace(named[0],'').trim():query;
   const request=fullRelease?(practiceRequest(search)??(awaitingTopic&&!intent?{topic:search,count:1}:null)):null;
   if(fullRelease&&(!session.record||!intent)){
    const match=await exactLibraryRecord(query,effective).catch(()=>null)??(named?await exactLibraryRecord(search,effective).catch(()=>null):null);
    if(beforeLoad!==version)return null;
    if(match)return startFull(match.record,beforeLoad);
   }
   if(request&&(!intent||request.topic||request.another)){
    const topic=request.topic||exampleTopic||session.record?.topic;
    if(!topic){awaitingTopic=true;return {kind:'clarify',text:'What topic should the practice question cover?'};}
    awaitingTopic=false;
    if(request.topic&&normal(request.topic)!==normal(exampleTopic??''))examples.clear();
    exampleTopic=topic;
    const options={topic,course:effective,exclude:[...examples],count:request.count};
    const practices=await findChatRecords({...options,kind:'practice'});
    const focused=practices.filter(item=>item.phrase);
    const concepts=focused.length?[]:await findChatRecords({...options,kind:'question'});
    const checks=focused.length?focused:concepts.length?concepts:practices;
    if(beforeLoad!==version)return null;
    if(!checks.length)return {kind:'clarify',text:examples.size?
     'I ran out of close matches for this topic. Name a more specific concept or choose another topic.':
     'I couldn’t find a close practice question for that wording. Try naming the specific concept or method.'};
    for(const item of checks)examples.add(item.position);
    if(checks.length===1)return startFull(checks[0].record,beforeLoad,{asExercise:true});
    return {kind:'matches',text:'Choose a question to try. You can ask for hints and see the worked explanation.',matches:checks,exercise:true};
   }
   await ready();if(beforeLoad!==version)return null;
   const exact=index.find(r=>(!effective||r.courses.includes(effective)||r.primary_collection==='RESOURCES')&&
    (r.record_kind==='practice'?exactQuestion(r.question)===exactQuestion(search):
     normal(r.question)===normal(search)||(r.aliases??[]).some(a=>normal(a)===normal(search))));
   if(exact){const record=await getRecord(exact);if(beforeLoad!==version)return null;activeSources=null;exercise=false;return {...session.start(record),sources,record};}
   if(/^(?:what (?:is|are)|define)\b/i.test(search)&&!/[0-9]/.test(search)&&!intent){session.reset();return null;}
   if(intent&&session.record){const response=await session.respond(query);return response?{...response,sources:activeSources??sources,record:session.record,exercise}:null;}
   if(intent&&!session.record&&!['rounding','units','check-answer'].includes(intent))return {...await session.respond(query),sources:sources??{},record:null};
   const ticket=++version;
   await ready();if(ticket!==version)return null;
   const candidates=rankLibrary(search,index,effective),best=candidates[0],second=candidates[1];
   if(!best||best.score<6.2||best.coverage<.65||(!best.exact&&second&&best.score-second.score<.4)){session.reset();return null;}
   let record=await getRecord(best.record);if(ticket!==version)return null;
   // A different number must never receive an old problem's answer.
   if(record.record_kind==='practice'&&!best.exact){
    const asked=numberSet(query),stored=numberSet(record.question);
    if([...asked].some(n=>!stored.has(n))){
     if(record.calculator?.family==='mass-moles'){
      const mass=/(-?\d+(?:\.\d+)?)\s*g\s*(?:of\s+)?(CO2|H2O|NaCl|O2)\b/.exec(query);
      const supplied=/(-?\d+(?:\.\d+)?)\s*g\s*\/\s*mol\b/i.exec(query);
      if(mass&&mass[2]===record.calculator.params.substance&&Number(mass[1])>0){
       const p={...record.calculator.params,mass:mass[1]};if(supplied&&Number(supplied[1])>0)p.molarMass=supplied[1];
       record=makePractice('mass-moles',p,{id:record.id,collection:record.primary_collection,course:record.courses[0],source_ids:record.source_ids,topic:record.topic});
      }else{session.reset();return {kind:'clarify',text:'This resembles a mass-to-moles exercise, but the quantities need a new setup. State the sample mass, substance, and molar mass; I will not reuse the example’s answer.',sources,source_ids:record.source_ids};}
     }else{session.reset();return {kind:'clarify',text:'The values differ from this checked exercise. Please state the givens with their units and which conditions stay fixed so we can set up a fresh calculation.',sources,source_ids:record.source_ids};}
    }
   }
   activeSources=null;exercise=false;
   const response=session.start(record);return {...response,sources,record};
  },
  observeLegacy(question,explanation,links=[]){
   reset();sources??={};const ids=links.map((link,i)=>{const id='current-reply-source-'+i;sources[id]={id,title:link.title,url:link.url,locator:'Source linked in the current BridgeAssist reply',status:'existing_reply_link_not_reverified'};return id;});
   session.start({id:'current-legacy-explanation',record_kind:'legacy-context',question,first_tutoring_reply:explanation,diagnostic_question:'Which specific step or value would you like to examine?',reference_answer:explanation,source_ids:ids,
    progressive_hints:['Paste the numerical value and its unit so I can identify the step.'],provenance:[],methods:[{title:'Current explanation',steps:[{title:'Revisit the explanation',explanation}]}],worked_solution:[{title:'Current explanation',explanation,checkpoint:'Which specific step is unclear?'}]});
  }
 };
}

const add=(host,tag,text,className)=>{const node=document.createElement(tag);node.textContent=text;if(className)node.className=className;host.append(node);return node;};
export function renderLearningReply(host,result,ask,choose){
 const block=add(host,'section','','learning-reply');
 if(result.matches&&choose){
  const list=add(block,'ol','','learning-matches');
  for(const item of result.matches){
   const row=add(list,'li','');
   const button=add(row,'button',item.record.question);
   button.type='button';button.addEventListener('click',()=>choose(item,result.exercise));
  }
 }
 if(result.kind==='start'&&result.record?.review_status)add(block,'p','Draft learning material. Verify details with the linked sources.','learning-draft-status');
 if(result.question)add(block,'p',result.question,'learning-active-question');
 for(const step of result.steps??[]){add(block,'h4',step.title);add(block,'p',step.explanation);}
 if(result.equivalence)add(block,'p',result.equivalence);
 if(result.prompt)add(block,'p',result.prompt,'learning-checkpoint');
 if(result.record?.unit_chain?.length&&(!(result.kind==='start'&&result.exercise))&&['start','units','full-solution','recalculated'].includes(result.kind)){
  const chain=add(block,'div','','learning-unit-chain');chain.setAttribute('aria-label','Dimensional-analysis setup; crossed-out unit pairs cancel.');
  result.record.unit_chain.forEach((factor,index)=>{
   if(index)add(chain,'span','×');const fraction=add(chain,'span','','learning-fraction');
   for(const position of ['top','bottom']){
    const quantity=factor[position];if(!quantity)continue;const line=add(fraction,'span',quantity.value,position);
    for(const unit of quantity.units){line.append(document.createTextNode(' '));const mark=add(line,unit.cancel?'s':'span',unit.text);if(unit.cancel)mark.title='This unit cancels with its matching numerator or denominator unit.';}
   }
  });
 }
 if(result.kind==='start'&&result.record?.record_kind==='practice'&&result.record.word_problem_breakdown){
  const details=add(block,'details','');add(details,'summary','Read the problem wording');const table=add(details,'table','');
  const header=add(table,'tr','');for(const title of ['Wording','Meaning','Role'])add(header,'th',title);
  for(const part of result.record.word_problem_breakdown){const row=add(table,'tr','');for(const key of ['phrase','meaning','role'])add(row,'td',part[key]);}
 }
 if(result.nodes?.length){const list=add(block,'ul','');for(const n of result.nodes)add(list,'li',`${n.display} — ${n.label}. ${n.explanation}`);}
 const links=add(block,'div','','source-links');
 for(const id of result.source_ids??[]){const source=result.sources?.[id];if(!source||!/^https?:\/\//.test(source.url))continue;const link=add(links,'a',source.title);link.href=source.url;link.target='_blank';link.rel='noopener noreferrer';link.title=source.locator??'';}
 for(const resource of result.record?.resource_links??[]){if(!/^(?:https?:\/\/|\/(?!\/))/.test(resource.url))continue;const link=add(links,'a',resource.title);link.href=resource.url;link.target='_blank';link.rel='noopener noreferrer';}
 if(result.record&&ask){const controls=add(block,'div','','learning-followups');
  const actions=[['Next step','Next step'],['Another method','Is there another way to solve this?'],['Where did that number come from?','How did you get that number?'],['Show full explanation','Show the complete worked solution']];
  if(result.exercise)actions.unshift(['Hint','Give me a hint']);
  if(result.exercise)actions.push(['Another example','Another example']);
  for(const [label,prompt] of actions){const button=add(controls,'button',label);button.type='button';button.addEventListener('click',()=>ask(prompt));}}
}

