// A session belongs to one mounted chat. It never stores a shared/global student problem.
const tidy=text=>String(text??'').normalize('NFKC').replace(/[’‘]/g,"'").replace(/[−–]/g,'-').toLowerCase().replace(/\s+/g,' ').trim();
const numbers=text=>[...String(text).matchAll(/(?<![\w.])-?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/g)].map(m=>({text:m[0],value:Number(m[0])}));
const near=(a,b)=>Math.abs(a-b)<=Math.max(1e-12,Math.abs(b)*1e-8);
export function followUpIntent(text){
 const q=tidy(text);
 if(/^(?:new (?:topic|question|problem)|start over|forget (?:this|that|it))\b/.test(q))return 'reset';
 if(/\b(?:what if|what about|instead use|change|replace|same problem but)\b/.test(q)&&numbers(q).length)return 'change-values';
 if((/\b(?:where|how)\b.*\b(?:get|got|come|came|find|found|obtain|arrive|calculate|reach)\b/.test(q)&&(numbers(q).length||/\b(?:this|that|these|those|number|value|coefficient)\b/.test(q)))||/\bwhy\b.*\b(?:this|that) number\b/.test(q))return 'number-origin';
 if(/(?:another|other|different|second|alternate|alternative|easier) (?:way|method|approach)|solve (?:it|this|that).*differently|use (?:a )?proportion|without (?:dimensional analysis|a punnett)/.test(q))return 'alternate-method';
 if(/\b(?:sig(?:nificant)?\s*fig|round|rounding|decimal places|trailing zero)/.test(q))return 'rounding';
 if(/\b(?:cancel|cancellation|why.*units?|why.*(?:multiply|divide)|flip.*fraction|invert)/.test(q))return 'units';
 if(/\b(?:source|sources|reference|references|citation|cite|where.*read|back.*up)/.test(q))return 'sources';
 if(/\b(?:check (?:my|this) (?:answer|work|result)|is (?:my answer|this|that) (?:right|correct)|i got|my answer is)\b/.test(q)||(/\bis\b.*\b(?:right|correct)\b/.test(q)&&numbers(q).length))return 'check-answer';
 if(/\b(?:show|give|explain|see)\b.*\b(?:full|complete|worked|whole)\b.*\b(?:solution|answer|example|problem)|\bshow (?:the )?(?:answer|solution)\b/.test(q))return 'full-solution';
 if(/^(?:please )?(?:give me|show me|can i have|i need|can i get) (?:a )?hint[?!. ]*$/.test(q))return 'practice-hint';
 if(/\b(?:next step|what next|continue|keep going|another hint|help me start|how do i start)\b|^(?:next|hint|yes|ok|okay|i don'?t know)[?!. ]*$/.test(q))return 'next-step';
 if(/^(?:please )?(?:walk me through|help me solve|how (?:do|should) i solve) (?:this|it|this problem)[?!. ]*$/.test(q))return 'next-step';
 if(/\bstep\s*\d+\b|^(?:why|how (?:so|come)|explain (?:it|that|this)(?: again)?|i (?:still )?don'?t understand|what does (?:it|that|this) mean|can you explain more)[?!. ]*$/.test(q))return 'explain-step';
 return null;
}

export class LearningSession {
 constructor({recalculate}={}){this.recalculate=recalculate;this.reset();}
 reset(){this.revision=(this.revision??0)+1;this.record=null;this.step=-1;this.focus=null;this.visible=new Set();this.method=0;this.turn=0;}
 start(record){
  this.reset();this.record=structuredClone(record);this.turn++;
  for(const node of record.provenance??[])if((node.origin==='given'||node.origin==='provided_constant')&&node.visible_initially!==false)this.visible.add(node.id);
  return {kind:'start',text:record.first_tutoring_reply,question:record.question,prompt:record.diagnostic_question,source_ids:record.source_ids,record_id:record.id};
 }
 #reply(kind,text,extra={}){return {kind,text,source_ids:this.record?.source_ids??[],record_id:this.record?.id,...extra};}
 #step(index){
  const steps=this.method===0?this.record.worked_solution:this.record.methods[this.method].steps;
  if(index<0||index>=steps.length)return this.#reply('clarify','Which step do you mean? '+steps.map((s,i)=>`${i+1}: ${s.title}`).join('; '));
  this.step=index;const step=steps[index];this.focus=step.node_id??null;
  if(this.focus)this.visible.add(this.focus);
  return this.#reply('step',step.explanation,{steps:[step],prompt:step.checkpoint??this.record.diagnostic_question});
 }
 #origin(text){
  const graph=this.record.provenance??[];
  const query=numbers(text);let candidates=[];
  if(query.length){
   candidates=graph.filter(node=>node.value!==undefined&&query.some(n=>near(n.value,Number(node.value))));
   const hasUnit=/\b(?:mol|mmol|g|kg|mg|ml|l|k|j|kj|atm|percent|%)\b/i.exec(text)?.[0];
   if(hasUnit){const withUnit=candidates.filter(n=>tidy(n.unit??'')===tidy(hasUnit));if(withUnit.length)candidates=withUnit;}
  }else if(this.focus)candidates=graph.filter(n=>n.id===this.focus);
  else candidates=graph.filter(n=>this.visible.has(n.id));
  if(candidates.length>1&&query.length){
   const exact=candidates.filter(n=>query.some(q=>q.text===String(n.value)));
   if(exact.length===1)candidates=exact;
   else if(candidates.length===2&&candidates.some(n=>n.origin==='rounded')&&candidates.some(n=>n.origin==='calculated')&&near(Number(candidates[0].value),Number(candidates[1].value)))candidates=candidates.filter(n=>n.origin==='rounded');
  }
  if(candidates.length!==1){
   const options=candidates.length?candidates:graph.filter(n=>this.visible.has(n.id));
   return this.#reply('clarify',options.length?'Which value do you mean? '+options.map(n=>`${n.display} (${n.label})`).join('; '):'Which number or step do you mean? Paste it, including its unit.');
  }
  const node=candidates[0];this.focus=node.id;this.visible.add(node.id);
  const parents=(node.input_ids??[]).map(id=>graph.find(n=>n.id===id)).filter(Boolean);
  const origin=node.origin==='given'?'That value is stated in the problem.':node.origin==='provided_constant'?'That value is supplied for this exercise; it is not a new measurement or a calculation from the student’s data.':node.origin==='formula_count'?'That value is counted from the chemical formula.':node.origin==='rounded'?'That is the reported, rounded value.':'That value is calculated from earlier quantities.';
  return this.#reply('number-origin',[`${node.display}: ${origin}`,node.explanation,node.expression?`Calculation: ${node.expression}`:'',parents.length?'Inputs: '+parents.map(p=>`${p.display} (${p.label})${p.expression?' — '+p.expression:''}`).join('; '):''].filter(Boolean).join('\n'),{nodes:[node,...parents],source_ids:node.source_ids??this.record.source_ids});
 }
 #alternate(text){
  const methods=this.record.methods??[];
  const requested=tidy(text).includes('proportion')?methods.findIndex(m=>/proportion/i.test(m.title)):-1;
  const next=requested>=0?requested:methods.findIndex((_,index)=>index!==this.method);
  if(next<0)return this.#reply('no-alternate','I do not have a separately checked second method for this item yet. I can explain the current setup or check your next step.');
  this.method=next;this.step=0;this.focus=null;const method=methods[next];
  return this.#reply('alternate-method',`We can use ${method.title.toLowerCase()} with the same problem and givens. ${method.why_valid}`,{steps:method.steps.slice(0,1),prompt:method.checkpoint??'How would you set up the first step?',equivalence:method.equivalence});
 }
 async respond(text){
  const intent=followUpIntent(text);if(!intent)return null;
  if(intent==='reset'){this.reset();return {kind:'reset',text:'Start a new problem or topic whenever you are ready.',source_ids:[]};}
  if(!this.record)return {kind:'clarify',text:'Which problem or explanation are you referring to? Paste it so I can connect the follow-up to the right values and steps.',source_ids:[]};
  this.turn++;
  if(intent==='number-origin')return this.#origin(text);
  if(intent==='alternate-method')return this.#alternate(text);
  if(intent==='sources')return this.#reply('sources','These references support the active explanation. The original practice values are identified separately from sourced scientific relationships.');
  if(intent==='rounding')return this.#reply('rounding',this.record.rounding_explanation??'This is a conceptual answer, so a significant-figure calculation does not apply. If you mean a numerical example, paste its measured values.');
  if(intent==='practice-hint')return this.#reply('hint',this.record.diagnostic_question??'Identify the concept or relationship the question asks you to use.');
  if(intent==='units')return this.#reply('units',this.record.unit_explanation??'This item does not use a unit-conversion chain. Tell me which term or relationship you would like explained.');
  if(intent==='next-step')return this.#step(Math.min(this.step+1,(this.method===0?this.record.worked_solution:this.record.methods[this.method].steps).length-1));
  if(intent==='explain-step'){
   const requested=/\bstep\s*(\d+)/i.exec(text);return this.#step(requested?Number(requested[1])-1:Math.max(0,this.step));
  }
  if(intent==='full-solution'){
   for(const step of this.record.worked_solution)if(step.node_id)this.visible.add(step.node_id);
   this.step=this.record.worked_solution.length-1;this.focus=this.record.worked_solution.at(-1)?.node_id??null;
   return this.#reply('full-solution',this.record.reference_answer,{steps:this.record.worked_solution});
  }
  if(intent==='change-values'){
   if(!this.recalculate||!this.record.calculator)return this.#reply('clarify','That change needs a fresh calculation. State the new quantity, its unit, and what stays the same; I will not reuse the old numerical answer.');
   const revision=this.revision;
   const result=await this.recalculate(this.record,text);
   if(revision!==this.revision)return null;
   if(!result?.record)return this.#reply('clarify',result?.clarification??'Which given should change? Include its label and unit.');
   const reply=this.start(result.record);return {...reply,kind:'recalculated',text:'I updated the problem and recalculated its solution; the earlier result does not carry over. '+reply.text};
  }
  if(intent==='check-answer'){
   const proposed=numbers(text);const expected=this.record.answer_numeric;
   if(expected===undefined||proposed.length!==1)return this.#reply('clarify','Paste the answer and the relevant working step. I need a single result with its unit to check this precisely.');
   const n=proposed[0];const target=Number(this.record.answer_display_numeric??expected);
   const unitText=text.slice(text.indexOf(n.text)+n.text.length).trim().replace(/[?.!]$/,'').trim();
   if(!this.record.accepted_units?.some(u=>tidy(u)===tidy(unitText)))return this.#reply('check-answer',`Include the result’s unit. The target unit here is ${this.record.answer_unit}; a matching number alone is not enough.`);
   const compared=this.record.answer_kind==='fraction'&&unitText==='%'?n.value/100:n.value;
   if(!near(compared,target))return this.#reply('check-answer','That does not match the checked result for these givens. '+this.record.progressive_hints[Math.max(0,Math.min(this.step+1,2))]);
   const sig=this.record.answer_sigfigs;
   if(sig&&countSigfigs(n.text)!==sig)return this.#reply('check-answer',`The magnitude and unit agree, but check how you report precision. ${this.record.rounding_explanation}`);
   return this.#reply('check-answer','Your numerical result, unit, and required precision match the checked solution. '+this.record.reasonableness_check);
  }
  return null;
 }
}

export function countSigfigs(value){
 const [mantissa]=String(value).trim().replace(/^[+-]/,'').split(/[eE]/);
 if(!/[1-9]/.test(mantissa))return null;
 const digits=mantissa.replace('.','').replace(/^0+/,'');
 if(mantissa.includes('.'))return digits.length;
 if(/[eE]/.test(value))return digits.length;
 return digits.replace(/0+$/,'').length;
}

import {libraryManifest, libraryPage, libraryRecord, libraryTokens, normalizeQuestion} from './full-library.mjs?v=library-4';

export function practiceRequest(query) {
  const text = query.trim().replace(/[?.!]+$/, '').replace(/\bword problems?\b/gi, match =>
    match.toLowerCase().endsWith('s') ? 'practice problems' : 'practice problem');
  const another = /^(?:(?:give|show) me )?(?:one more|another)(?: (?:example|question|problem|one|exercise))?(?: (?:of|on|about|for) (.+?))?(?: please)?$/i.exec(text);
  if (another) {
    return {topic: another[1] ?? '', another: true, count: 1};
  }
  const match = /^(?:(?:can|could|would) you\s+)?(?:please\s+)?(?:(?:(?:give|show|find|make|write|provide|generate|create)\s+(?:me\s+)?|(?:i (?:want|need|would like)\s+))(?:(a few|some|one|two|three|four|five|\d+)\s+|an?\s+)?(?:(?:easy|simple|basic|hard|challenging|worked)\s+)?((?:example|sample|practice|quiz|review)(?:\s+(?:question|problem|exercise|prompt))?s?|questions?|problems?|exercises?|prompts?)|(?:quiz|test) me|(?:help me )?practice|(?:let'?s )?practice)(?:\s+(?:(?:of|about|on|for|with|using|in)\s+)?(.+?))?(?:\s+please)?$/i.exec(text);
  if (!match) return null;
  const writtenCount = ['one', 'two', 'three', 'four', 'five'].indexOf(match[1]?.toLowerCase()) + 1;
  const count = Math.max(1, Math.min(5, Number(match[1]) || writtenCount || (match[1] || /s$/i.test(match[2] ?? '') ? 3 : 1)));
  return {topic: match[3]?.trim() ?? '', another: false, count};
}

const ignore = new Set('concept topic type section chapter chemistry biology science please tell explain describe understand show example sample practice problem exercise question prompt quiz review find learn need want about relating related something course supplemental basic beginner student'.split(' '));
const termsFor = topic => libraryTokens(topic).filter(term => !ignore.has(term));
const coverage = (terms, text) => {
  const words = new Set(libraryTokens(text));
  return terms.filter(term => words.has(term)).length;
};
const includesPhrase = (terms, text) => (' ' + normalizeQuestion(text).replace(/[^a-z\d ]+/g,' ').replace(/\s+/g,' ') + ' ')
  .includes(' ' + terms.join(' ') + ' ');

function focusCheck(record, terms) {
  if (record.family_id !== 'mixed-concept-review') return record;
  const checks = record.component_questions.map((question, index) => {
    const step = record.worked_solution[index];
    const topic = step.title.replace(/^[A-C]\. /, '');
    const named = /[“"]([^”"]+)[”"]/.exec(question)?.[1];
    if(named && !includesPhrase(terms,named) && includesPhrase(terms,question)) return null;
    const score = coverage(terms, question + ' ' + topic) +
      (includesPhrase(terms,named ?? question)?terms.length*2:0);
    return {question, step, topic, score, index};
  }).filter(Boolean).sort((a, b) => b.score - a.score);
  const best = checks[0];
  if (!best?.score || coverage(terms, best.question + ' ' + best.topic) < terms.length) return null;
  const sourceIds = record.claim_source_links[best.index].source_ids;
  const step = {...best.step, title: 'Explanation'};
  return {...record, topic: best.topic, question: best.question,
    source_ids: sourceIds, first_tutoring_reply: step.explanation,
    diagnostic_question: 'Which part of the question would you explain first?',
    reference_answer: step.explanation, worked_solution: [step],
    methods: [{title: 'Explain the concept', steps: [step]}]};
}

export async function findChatRecords({topic, course, kind, exclude = [], count = 1}) {
  const terms = termsFor(topic);
  if (!terms.length || terms.length > 12 || terms.every(term => /^\d|^\w{1,2}$/.test(term))) return [];
  const result = await libraryPage({query: terms.join(' '), course, kind, exclude, chat: true});
  const primary = await select(result.results);
  if (primary.length || course || kind !== 'question') return primary;
  // A mixed review can contain a search term in a second or third check.
  // Search academic collections individually if none of the global results has a focused check.
  const manifest = await libraryManifest();
  const collections = manifest.collections.filter(item => item.course !== 'RESOURCES');
  const pages = await Promise.all(collections.map(item =>
    libraryPage({query:terms.join(' '), course:item.course, kind, exclude, chat:true})
  ));
  return select(pages.flatMap(page => page.results));

  async function select(items) {
   const ranked = items.filter(item => item.course !== 'RESOURCES' || course === 'RESOURCES')
    .map(item => ({
      ...item,
      confidence: coverage(terms, item.topicTerms ?? item.topic),
      phrase: includesPhrase(terms, item.topicTerms ?? item.topic) || includesPhrase(terms,item.question),
      wordCount: item.question.length
    }))
    .sort((a, b) => Number(b.phrase) - Number(a.phrase) || b.confidence - a.confidence || a.wordCount - b.wordCount || a.position - b.position);
   const selected = [];
   const seen = new Set();
   for (const item of ranked) {
    const record = focusCheck(await libraryRecord(item.position), terms);
    if (!record || seen.has(record.question)) continue;
    seen.add(record.question);
    selected.push({...item, record, requestedTopic:topic});
    if (selected.length >= count) break;
   }
   return selected;
  }
}

import {countSigfigs} from './learning-session.mjs';
const num=x=>Number(x);
const sf=(value,digits)=>Number(value)===0?'0':Number(value).toPrecision(digits).replace('e+','e');
const text=x=>String(x);
const minSF=(...values)=>Math.min(...values.map(x=>countSigfigs(String(x))).filter(x=>x!==null));
const node=(id,label,value,unit,origin,explanation,inputs=[],expression='')=>({id,label,value:String(value),unit,display:`${value}${unit?' '+unit:''}`,origin,explanation,input_ids:inputs,expression});
export function makePractice(family,p,meta={}){
 let question,answer,unit,sig,rounding,steps,methods,graph,explanation,unitExplanation,checkpoint,reason,check;
 const input=(id,label,key,u)=>node(id,label,p[key],u,'given','This quantity is stated in the question.');
 const method=(title,why_valid,work,equivalence)=>({title,why_valid,steps:work.map((explanation,i)=>({title:`Step ${i+1}`,explanation})),equivalence,checkpoint:'Set up the relationship with the same givens before calculating.'});
 const step=(title,explanation,node_id,checkpoint)=>({title,explanation,node_id,checkpoint});
 if(family==='mass-moles'){
  unit='mol';sig=minSF(p.mass,p.molarMass);answer=num(p.mass)/num(p.molarMass);
  question=`How many moles are in ${p.mass} g of ${p.substance}? Use the supplied molar mass ${p.molarMass} g/mol.`;
  graph=[input('mass','sample mass','mass','g'),node('molar-mass','supplied molar mass',p.molarMass,'g/mol','provided_constant','The problem supplies this molar mass. It means this many grams per one mole of this substance; it is not calculated from the sample mass.'),node('amount','amount of substance',answer,unit,'calculated','Divide the sample mass by the mass per mole.',['mass','molar-mass'],`${p.mass} g / (${p.molarMass} g/mol) = ${answer} mol`)];
  const classroomAtoms={CO2:[['C','12.01',1],['O','16.00',2]],NaCl:[['Na','22.99',1],['Cl','35.45',1]],H2O:[['H','1.008',2],['O','16.00',1]],O2:[['O','16.00',2]]}[p.substance];
  if(classroomAtoms){
   const sum=classroomAtoms.reduce((s,[,m,c])=>s+Number(m)*c,0);
   if(sum.toFixed(2)===Number(p.molarMass).toFixed(2)){
    const extra=classroomAtoms.flatMap(([symbol,mass,count])=>[
     {...node('atomic-'+symbol,`${symbol} classroom atomic molar mass`,mass,'g/mol','provided_constant',`This is a rounded classroom periodic-table value for ${symbol}, not a mass measured from this sample.`),visible_initially:false},
     {...node('count-'+symbol,`${symbol} atoms per formula unit`,count,'','formula_count',`The formula ${p.substance} specifies ${count} ${symbol} atom${count===1?'':'s'} per molecule or formula unit.`),visible_initially:false}
    ]);
    graph[1].explanation+=` You can reconstruct this classroom value by summing the atomic molar masses with their formula counts: ${classroomAtoms.map(([s,m,c])=>`${c} × ${m} (${s})`).join(' + ')} = ${sum} g/mol, reported here as ${p.molarMass} g/mol. These atomic values are rounded teaching values.`;
    graph[1].input_ids=extra.map(n=>n.id);graph[1].expression=classroomAtoms.map(([,m,c])=>`${c} × ${m}`).join(' + ')+` = ${sum} g/mol`;
    graph.splice(2,0,...extra);
   }
  }
  explanation='The target is an amount in moles. Molar mass connects the mass of this substance to its amount; no reacting second substance is involved.';
  unitExplanation=`Place grams in the denominator: ${p.mass} g × (1 mol / ${p.molarMass} g). The matching grams divide to 1 and mol remains. Multiplying by g/mol would instead leave g²/mol.`;
  steps=[step('Choose the conversion',unitExplanation,'molar-mass','Which unit must appear below the fraction to cancel the starting unit?'),step('Calculate the amount',`${p.mass} ÷ ${p.molarMass} = ${answer} mol before rounding.`,'amount','Does dividing by grams per mole leave moles?')];
  methods=[method('Dimensional analysis','The conversion factor is the supplied mass per mole.',[unitExplanation],`n = m/M`),method('Ratio and proportion','The same mass-to-amount relationship can be written as an equality of ratios.',[`1 mol / ${p.molarMass} g = x mol / ${p.mass} g.`,`Cross-multiply: x × ${p.molarMass} = ${p.mass}; then divide by ${p.molarMass}.`],'Both setups rearrange m = nM and must give the same amount.')];
  checkpoint='What unit is requested, and which way should the molar-mass fraction face?';reason='Multiplying the resulting amount by the supplied molar mass should recover the starting mass.';
 } else if(family==='density'){
  unit='g/mL';sig=minSF(p.mass,p.volume);answer=num(p.mass)/num(p.volume);
  question=`A sample has mass ${p.mass} g and volume ${p.volume} mL. What is its density in g/mL?`;
  graph=[input('mass','sample mass','mass','g'),input('volume','sample volume','volume','mL'),node('density','sample density',answer,unit,'calculated','Density is mass divided by volume.',['mass','volume'],`${p.mass} / ${p.volume} = ${answer}`)];
  explanation='The requested quantity is mass per volume. The phrase g/mL specifies the order of division.';unitExplanation='Divide grams by milliliters. Neither g nor mL cancels here; both remain in the compound unit g/mL.';
  steps=[step('Identify numerator and denominator',unitExplanation,'mass','Which measured quantity belongs above the fraction?'),step('Divide',`${p.mass} g / ${p.volume} mL = ${answer} g/mL before rounding.`,'density')];
  methods=[method('Density equation','Use d = m/V.',[unitExplanation],'dV = m'),method('Unit-rate proportion','Find the mass corresponding to one milliliter.',[`Write x g / 1 mL = ${p.mass} g / ${p.volume} mL.`,`Divide both sides of the measured mass-to-volume ratio by ${p.volume}.`],'Both methods find the same grams per one milliliter.')];checkpoint='Does the target unit put mass or volume first?';reason='Density multiplied by sample volume should return sample mass.';
 } else if(family==='molarity'){
