export function recalculatePractice(record,utterance){
 const p=structuredClone(record.calculator.params);const q=utterance.replace(/−/g,'-');
 const values=[...q.matchAll(/(-?\d+(?:\.\d+)?)\s*(g|mL|L|mol|atm|K|°C)\b/gi)];
 if(values.length!==1)return {clarification:'State one changed given at a time, including its unit and whether it is initial or final. The other givens will stay fixed.'};
 const [,value,unit]=values[0];if(Number(value)<=0&&unit.toLowerCase()!=='°c')return {clarification:'This family needs a positive mass, volume, pressure, amount, or absolute temperature.'};
 const family=record.calculator.family;let key;
 if(family==='mass-moles'&&unit==='g'){
  const named=/\bg\s+(?:of\s+)?([A-Z][A-Za-z0-9()]+)/.exec(q)?.[1];
  if(named&&named!==p.substance)return {clarification:'That changes the substance as well as the mass. Supply its molar mass; the old substance’s molar mass must not carry over.'};
  key='mass';
 }else if(family==='density')key=unit==='g'?'mass':unit==='mL'?'volume':undefined;
 else if(family==='molarity')key=unit==='mol'?'amount':unit==='mL'?'volumeML':undefined;
 else if(family==='dilution'&&unit==='mL')key=/final/i.test(q)?'finalML':/initial|starting|aliquot/i.test(q)?'initialML':undefined;
 else if(family==='boyle')key=unit==='atm'?'p1':unit==='L'&&/final/i.test(q)?'v2':unit==='L'&&/initial|starting/i.test(q)?'v1':undefined;
 else if(family==='charles')key=unit==='L'?'v1':unit==='K'&&/final/i.test(q)?'t2':unit==='K'&&/initial|starting/i.test(q)?'t1':undefined;
 else if(family==='calorimetry')key=unit==='g'?'mass':unit==='°C'&&/final/i.test(q)?'tf':unit==='°C'&&/initial|starting/i.test(q)?'ti':undefined;
 if(!key)return {clarification:'Which given should change? Specify its label and use the original unit; an unlabeled initial/final change is ambiguous.'};
 p[key]=value;
 if(family==='dilution'&&Number(p.finalML)<Number(p.initialML))return {clarification:'A dilution by adding solvent cannot have a final solution volume smaller than the original aliquot. Check which volume changed.'};
 return {record:makePractice(family,p,{id:record.id,collection:record.primary_collection,course:record.courses[0],source_ids:record.source_ids,topic:record.topic})};
}

const page = new URL(location.href);
const mode = document.body.dataset.chatMode;
const destination = new URL('/assistant.html', page);
destination.searchParams.set(mode, '1');
for (const key of ['q', 'course', 'type', 'page', 'question', 'library']) {
  if (page.searchParams.has(key)) destination.searchParams.set(key, page.searchParams.get(key));
}
if (mode === 'practice' && !destination.searchParams.has('q')) {
  const topic = page.searchParams.get('topic');
  if (topic) destination.searchParams.set('q', topic.replaceAll('-', ' '));
}
if (page.pathname.includes('/conversation') && !destination.searchParams.has('type')) {
  destination.searchParams.set('type', 'question');
}
location.replace(destination);
